args:
$ErrorActionPreference = 'Stop'
$projectRoot = (Get-Location).Path

try {
    $package = Get-Content -LiteralPath (Join-Path $projectRoot 'package.json') -Raw -Encoding UTF8 | ConvertFrom-Json
    $releaseDirectory = Join-Path $projectRoot 'releases/current'
    New-Item -ItemType Directory -Path $releaseDirectory -Force | Out-Null
    $vsix = Join-Path $releaseDirectory ($package.name + '-' + $package.version + '.vsix')
    $npm = (Get-Command npm.cmd -ErrorAction Stop).Source

    $codeCli = $null
    if ($env:WALLPAPER_STUDIO_CODE_EXECUTABLE) {
        $candidate = Join-Path (Split-Path -Parent $env:WALLPAPER_STUDIO_CODE_EXECUTABLE) 'bin/code.cmd'
        if (Test-Path -LiteralPath $candidate -PathType Leaf) { $codeCli = $candidate }
    }
    if (-not $codeCli) { $codeCli = (Get-Command code.cmd -ErrorAction Stop).Source }

    Push-Location -LiteralPath $projectRoot
    try {
        & $npm run package
        if ($LASTEXITCODE -ne 0) { throw "Build/package failed (exit $LASTEXITCODE). Installation skipped." }
        if (-not (Test-Path -LiteralPath $vsix -PathType Leaf)) { throw "VSIX was not generated: $vsix" }

        & $codeCli --install-extension $vsix --force
        if ($LASTEXITCODE -ne 0) { throw "Extension installation failed (exit $LASTEXITCODE)." }
        Write-Host "Installed $($package.publisher).$($package.name)@$($package.version). Run Developer: Reload Window to activate."
    } finally {
        Pop-Location
    }
} catch {
    [Console]::Error.WriteLine($_.Exception.Message)
    exit 1
}
